$ErrorActionPreference='Continue';$Root=Split-Path -Parent $PSScriptRoot;. "$PSScriptRoot/local-runtime-common.ps1";Import-SigovEnv "$Root/.env.local";Assert-SigovVariables
function Proc($n){$f="$Root/.local/run/$n.pid";if(!(Test-Path $f)){return 'Stopped'};$p=Get-Process -Id (Get-Content $f) -ErrorAction SilentlyContinue;if($p){'Running'}else{Remove-Item $f -Force;'Stopped'}}
function Http($u){try{$r=Invoke-WebRequest $u -TimeoutSec 5 -UseBasicParsing;if($r.StatusCode -lt 400){'OK'}else{'Erro'}}catch{'Erro'}}
$db='OK';$schema='OK';try{$schema="$(Invoke-RuntimePsql "select exists(select 1 from information_schema.schemata where schema_name='sigov')")";if($schema -notmatch 't|true|1'){$schema='Erro'}else{$schema='OK'}}catch{$db='Erro';$schema='Erro'}
$result=[ordered]@{timestamp=(Get-Date).ToUniversalTime().ToString('o');api=(Proc api);web=(Proc web);worker=if(($env:SIGOV_RUN_WORKER??'false') -eq 'true'){Proc worker}else{'Desabilitado'};database=$db;runtimeUser=$db;schema=$schema;healthLive=(Http "$env:SIGOV_API_URL/api/health/live");healthReady=(Http "$env:SIGOV_API_URL/api/health/ready");webHome=(Http $env:SIGOV_WEB_URL);migrationMode=$env:SIGOV_MIGRATION_MODE}
[pscustomobject]$result|Format-List; $dir="$Root/artifacts/local-setup";Write-SafeJson $result "$dir/status-result.json";$lines=@('# Status local SIGOV+','',"Gerado: $($result.timestamp)",'','| Item | Status |','|---|---|')+@($result.Keys|ForEach-Object{"| $_ | $($result[$_]) |"});$lines|Set-Content "$dir/status-report.md";if($db -eq 'Erro' -or $result.healthReady -eq 'Erro'){exit 2}
